(()=>{const section=document.querySelector('#about'),reduced=matchMedia('(prefers-reduced-motion: reduce)');let target=0,current=0,frame=0,last=0;const clamp=v=>Math.max(0,Math.min(1,v));function paint(){section.style.setProperty('--philosophy-progress',current.toFixed(5));section.style.setProperty('--detail-reveal',clamp((current-.2)/.65).toFixed(5));}function tick(now){const dt=last?Math.min((now-last)/1000,.05):1/60;last=now;current+= (target-current)*(1-Math.exp(-dt*9));if(Math.abs(target-current)<.0005){current=target;frame=0;last=0;paint();return;}paint();frame=requestAnimationFrame(tick);}function update(){const box=section.getBoundingClientRect(),distance=Math.max(1,section.offsetHeight-innerHeight);const raw=clamp(-box.top/distance/.8);target=Math.max(target,reduced.matches?1:raw);if(reduced.matches){cancelAnimationFrame(frame);frame=0;current=1;paint();return;}if(!frame&&target>current){last=0;frame=requestAnimationFrame(tick);}}addEventListener('scroll',update,{passive:true});addEventListener('resize',update);reduced.addEventListener('change',update);paint();update();})();